import{_ as a,o as i,c as n,a2 as l}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"División Unificada de los Niveles de Cultivo","description":"","frontmatter":{},"headers":[],"relativePath":"es/0014-修炼境界统一划分.md","filePath":"es/0014-修炼境界统一划分.md"}'),o={name:"es/0014-修炼境界统一划分.md"};function d(r,e,s,t,c,u){return i(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="division-unificada-de-los-niveles-de-cultivo" tabindex="-1">División Unificada de los Niveles de Cultivo <a class="header-anchor" href="#division-unificada-de-los-niveles-de-cultivo" aria-label="Permalink to &quot;División Unificada de los Niveles de Cultivo&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>14</td></tr><tr><td>Módulo</td><td>Leyes Cósmicas y Sistemas de Cultivo</td></tr><tr><td>Palabras clave</td><td>División de Niveles, Estándar Unificado, Nueve Niveles, Comparación entre Sistemas, Certificación de Anclas</td></tr></tbody></table><h2 id="i-la-necesidad-de-la-division-unificada-de-niveles" tabindex="-1">I. La Necesidad de la División Unificada de Niveles <a class="header-anchor" href="#i-la-necesidad-de-la-division-unificada-de-niveles" aria-label="Permalink to &quot;I. La Necesidad de la División Unificada de Niveles&quot;">​</a></h2><p>Antes del establecimiento de la Civilización Simbiótica del Ancla, existían miles de sistemas de cultivo en Heng Yuan Zhou, cada uno con sus propios estándares independientes de división de niveles. Este caótico sistema de niveles condujo a una serie de problemas: la fuerza de los cultivadores de diferentes sistemas era difícil de comparar, la comunicación y colaboración entre sistemas carecía de un lenguaje común, la asignación de recursos y la evaluación del estatus social carecían de una base unificada, e incluso apareció la grave injusticia de &quot;mismo nivel, diferente poder&quot;.</p><p>Tras el establecimiento de la Civilización Simbiótica del Ancla, para resolver este problema, bajo el liderazgo del &quot;Comité de Estándares de Cultivo&quot; dependiente del Parlamento de la República de las Diez Mil Razas, junto con cultivadores representativos de los Trescientos Sistemas, se formuló este &quot;Estándar Unificado de División de Niveles de Cultivo&quot; tras una investigación y demostración de larga duración. Este estándar no se basa en los nombres de niveles de ningún sistema individual, sino que utiliza cuatro dimensiones como indicadores centrales — la profundidad de comprensión del cultivador de las leyes del Origen del universo, la precisión de la manipulación energética, el grado de evolución de la conciencia y la contribución a la red simbiótica — estableciendo un sistema de división de niveles universal entre sistemas.</p><p>El principio central de la división unificada de niveles es &quot;valorar la sustancia sobre el nombre&quot;: independientemente de qué sistema use un cultivador o qué nombre de nivel le ponga, mientras su sustancia alcance el nivel correspondiente del estándar unificado, es reconocido en ese nivel. Este principio garantiza la justicia y objetividad de la evaluación de niveles.</p><h2 id="ii-resumen-de-los-nueve-niveles" tabindex="-1">II. Resumen de los Nueve Niveles <a class="header-anchor" href="#ii-resumen-de-los-nueve-niveles" aria-label="Permalink to &quot;II. Resumen de los Nueve Niveles&quot;">​</a></h2><p>El estándar unificado de división de niveles divide el viaje evolutivo del cultivador en nueve grandes niveles, de menor a mayor:</p><table tabindex="0"><thead><tr><th>N.º de Nivel</th><th>Nombre del Nivel</th><th>Características Centrales</th><th>Nivel Aproximadamente Correspondiente de los Tres Fundamentos del Origen</th><th>Posicionamiento del Rol Social</th></tr></thead><tbody><tr><td>Primer nivel</td><td>Nivel de Percepción del Origen</td><td>Percibir preliminarmente la existencia de la energía y las leyes cósmicas, comenzar el cultivo formal</td><td>Visión Inicial / Percepción de la Vida / Reconocimiento del Espacio</td><td>Principiante</td></tr><tr><td>Segundo nivel</td><td>Nivel de Condensación del Origen</td><td>Absorber y condensar energía de forma estable, establecer circulación interna básica</td><td>Deducción / Circulación / Dominio del Espacio</td><td>Cultivador Junior</td></tr><tr><td>Tercer nivel</td><td>Nivel de Transformación del Origen</td><td>La purificación energética alcanza un nivel alto, transformar energía en diversas aplicaciones</td><td>Iteración / Generación / Transformación del Espacio</td><td>Cultivador Intermedio</td></tr><tr><td>Cuarto nivel</td><td>Nivel de Ley del Origen</td><td>Comenzar a comprender y manipular leyes, fusión inicial de energía y leyes</td><td>Integración / Transformación de la Vida / Ley del Espacio</td><td>Cultivador Avanzado</td></tr><tr><td>Quinto nivel</td><td>Nivel de Dao del Origen</td><td>Comprensión profunda de las leyes de un campo, formando el &quot;Dao&quot; personal</td><td>Origen / Nacimiento del Origen / Origen del Espacio</td><td>Cultivador de Nivel Maestro</td></tr><tr><td>Sexto nivel</td><td>Nivel de Integración del Dao</td><td>El Dao personal se fusiona profundamente con las leyes del Origen del universo, cada movimiento conforme al Dao</td><td>Más allá del quinto nivel de un solo sistema</td><td>Cultivador de Nivel Gran Maestro</td></tr><tr><td>Séptimo nivel</td><td>Nivel de Ruptura de Fronteras</td><td>Romper las restricciones de las leyes de los planos, realizar operaciones estables entre planos</td><td>—</td><td>Experto de Nivel Plano</td></tr><tr><td>Octavo nivel</td><td>Nivel de Creación de Mundos</td><td>Crear mundos completos y sistemas de leyes en el Espacio de Aislamiento</td><td>—</td><td>Experto de Nivel Mundo</td></tr><tr><td>Noveno nivel</td><td>Nivel del Origen</td><td>Tocar el Origen del universo, participar en el ajuste fino y la optimización de las leyes cósmicas</td><td>—</td><td>Experto de Nivel Cósmico</td></tr></tbody></table><p>Entre los nueve niveles, del primero al quinto son los &quot;Cinco Niveles de Cultivo Mortal&quot;, alcanzables por la mayoría de los cultivadores mediante esfuerzo; del sexto al noveno son los &quot;Cuatro Niveles de Cultivo Sagrado&quot;, que requieren talento, fortuna y esfuerzo extremadamente altos — el avance de cada nivel es un evento mayor de nivel cósmico.</p><h2 id="iii-estandares-detallados-de-cada-nivel" tabindex="-1">III. Estándares Detallados de Cada Nivel <a class="header-anchor" href="#iii-estandares-detallados-de-cada-nivel" aria-label="Permalink to &quot;III. Estándares Detallados de Cada Nivel&quot;">​</a></h2><h3 id="_3-1-primer-nivel-percepcion-del-origen" tabindex="-1">3.1 Primer Nivel: Percepción del Origen <a class="header-anchor" href="#_3-1-primer-nivel-percepcion-del-origen" aria-label="Permalink to &quot;3.1 Primer Nivel: Percepción del Origen&quot;">​</a></h3><p>El Nivel de Percepción del Origen es el punto de partida del cultivo, con la &quot;percepción&quot; como núcleo. Los estándares para alcanzarlo incluyen:</p><ul><li>Percibir de forma estable la energía libre en el universo (qi espiritual, fuerza de leyes, etc.)</li><li>Absorber cantidades mínimas de energía en el cuerpo mediante métodos de cultivo básicos</li><li>Establecer una conciencia preliminar de percepción energética, capaz de distinguir diferentes tipos de energía</li><li>La calidad física muestra una mejora inicial debido a la infiltración energética</li></ul><p>Los cultivadores del Nivel de Percepción del Origen son &quot;principiantes&quot; en la sociedad, con la tarea principal de sentar bases sólidas y encontrar un sistema de cultivo adecuado. El avance generalmente requiere de varias semanas a varios meses de cultivo formal.</p><h3 id="_3-2-segundo-nivel-condensacion-del-origen" tabindex="-1">3.2 Segundo Nivel: Condensación del Origen <a class="header-anchor" href="#_3-2-segundo-nivel-condensacion-del-origen" aria-label="Permalink to &quot;3.2 Segundo Nivel: Condensación del Origen&quot;">​</a></h3><p>El núcleo del Nivel de Condensación del Origen es la &quot;condensación&quot;. Los estándares para alcanzarlo incluyen:</p><ul><li>Absorber energía cósmica de forma estable y condensarla en reservas de energía utilizables en el cuerpo</li><li>Establecer un sistema de circulación interna básico, la energía puede circular por caminos específicos en el cuerpo</li><li>Usar la energía condensada para aplicaciones ofensivas, defensivas o auxiliares básicas</li><li>La pureza energética alcanza el estándar básico, sin impurezas excesivas</li></ul><p>Los cultivadores del Nivel de Condensación del Origen ya poseen una identidad básica de cultivador y pueden participar en algunas tareas de cultivo de bajo nivel y servicios sociales. El avance generalmente requiere de varios meses a varios años de cultivo.</p><h3 id="_3-3-tercer-nivel-transformacion-del-origen" tabindex="-1">3.3 Tercer Nivel: Transformación del Origen <a class="header-anchor" href="#_3-3-tercer-nivel-transformacion-del-origen" aria-label="Permalink to &quot;3.3 Tercer Nivel: Transformación del Origen&quot;">​</a></h3><p>El núcleo del Nivel de Transformación del Origen es la &quot;transformación&quot;. Los estándares para alcanzarlo incluyen:</p><ul><li>La purificación energética alcanza un nivel alto, capaz de transformar un tipo de energía en otro</li><li>Realizar interacción preliminar entre energía y materia (como adherencia de energía a objetos, moldeado energético, etc.)</li><li>Circulación interna estable y eficiente, velocidad de recuperación energética muy mejorada</li><li>Comenzar a percibir la existencia y funcionamiento de las leyes</li></ul><p>Los cultivadores del Nivel de Transformación del Origen son la columna vertebral de la sociedad, pudiendo servir como mentores intermedios, personal técnico, gestores de base, etc. El avance generalmente requiere de varios años a más de una década de cultivo.</p><h3 id="_3-4-cuarto-nivel-ley-del-origen" tabindex="-1">3.4 Cuarto Nivel: Ley del Origen <a class="header-anchor" href="#_3-4-cuarto-nivel-ley-del-origen" aria-label="Permalink to &quot;3.4 Cuarto Nivel: Ley del Origen&quot;">​</a></h3><p>El núcleo del Nivel de Ley del Origen es la &quot;ley&quot;. Los estándares para alcanzarlo incluyen:</p><ul><li>Comprender y manipular preliminarmente las leyes básicas de un campo</li><li>Fusión inicial de energía y leyes, produciendo la &quot;fuerza de ley&quot; — una forma de energía de orden superior</li><li>Realizar hechizos y habilidades basados en leyes</li><li>La intensidad de la conciencia muy mejorada, capaz de deducción profunda y meditación prolongada</li></ul><p>Los cultivadores del Nivel de Ley del Origen son talentos avanzados en la sociedad, pudiendo servir como mentores superiores, expertos técnicos, gestores intermedios, etc. El avance generalmente requiere de más de una década a varias décadas de cultivo, siendo el primer gran cuello de botella en la vida de muchos cultivadores.</p><h3 id="_3-5-quinto-nivel-dao-del-origen" tabindex="-1">3.5 Quinto Nivel: Dao del Origen <a class="header-anchor" href="#_3-5-quinto-nivel-dao-del-origen" aria-label="Permalink to &quot;3.5 Quinto Nivel: Dao del Origen&quot;">​</a></h3><p>El núcleo del Nivel de Dao del Origen es &quot;formar el Dao&quot;. Los estándares para alcanzarlo incluyen:</p><ul><li>Comprensión sistemática y profunda de las leyes de un campo, formando un &quot;Dao&quot; personal único</li><li>El Dao personal resuena con las leyes cósmicas, capaz de movilizar fuerza de leyes en un mayor alcance</li><li>Fusión profunda de energía y leyes, cada movimiento contiene fuerza de leyes</li><li>La conciencia evoluciona a un nivel superior, capaz de percepción de conciencia entre planos</li></ul><p>Los cultivadores del Nivel de Dao del Origen son los &quot;maestros&quot; de la civilización, autoridades en sus respectivos campos, pudiendo servir como consejeros de nivel civilización, grandes mentores, gestores superiores, etc. El avance requiere talento y comprensión extremadamente altos; muchos cultivadores no pueden alcanzarlo en toda su vida.</p><h3 id="_3-6-sexto-nivel-integracion-del-dao" tabindex="-1">3.6 Sexto Nivel: Integración del Dao <a class="header-anchor" href="#_3-6-sexto-nivel-integracion-del-dao" aria-label="Permalink to &quot;3.6 Sexto Nivel: Integración del Dao&quot;">​</a></h3><p>El núcleo del Nivel de Integración del Dao es la &quot;integración del Dao&quot;. Los estándares para alcanzarlo incluyen:</p><ul><li>El Dao personal se fusiona profundamente con las leyes del Origen del universo, alcanzando el estado de &quot;unidad del cielo y el hombre&quot;</li><li>Reescribir el funcionamiento de las leyes locales en un gran alcance</li><li>La forma de vida comienza a evolucionar hacia dimensiones superiores, parcialmente libre de las limitaciones del cuerpo material</li><li>Crear un dominio personal estable (dominio de leyes)</li></ul><p>Los cultivadores del Nivel de Integración del Dao son los &quot;grandes maestros&quot; de la civilización, figuras cimeras en diversos campos, con influencia significativa en la dirección del desarrollo de la civilización. El avance es un evento de nivel cósmico, que requiere la coordinación del tiempo, el lugar y la armonía humana.</p><h3 id="_3-7-septimo-nivel-ruptura-de-fronteras" tabindex="-1">3.7 Séptimo Nivel: Ruptura de Fronteras <a class="header-anchor" href="#_3-7-septimo-nivel-ruptura-de-fronteras" aria-label="Permalink to &quot;3.7 Séptimo Nivel: Ruptura de Fronteras&quot;">​</a></h3><p>El núcleo del Nivel de Ruptura de Fronteras es &quot;romper las fronteras&quot;. Los estándares para alcanzarlo incluyen:</p><ul><li>Romper las restricciones de las leyes de los planos, realizar travesía entre planos sin apoyo de anclas</li><li>Operar sobre la membrana de los planos, como abrir canales entre planos, reparar grietas de planos</li><li>El dominio personal puede expandirse a un pequeño espacio independiente</li><li>La forma de vida se alta-dimensionaliza aún más, capaz de sobrevivir en los entornos de leyes de diferentes planos</li></ul><p>Los expertos del Nivel de Ruptura de Fronteras son existencias de &quot;nivel plano&quot;, capaces de emprender de forma independiente tareas y responsabilidades de nivel plano. El avance es extremadamente difícil; el número de cultivadores que alcanzan este nivel en todo Heng Yuan Zhou es limitado.</p><h3 id="_3-8-octavo-nivel-creacion-de-mundos" tabindex="-1">3.8 Octavo Nivel: Creación de Mundos <a class="header-anchor" href="#_3-8-octavo-nivel-creacion-de-mundos" aria-label="Permalink to &quot;3.8 Octavo Nivel: Creación de Mundos&quot;">​</a></h3><p>El núcleo del Nivel de Creación de Mundos es la &quot;creación de mundos&quot;. Los estándares para alcanzarlo incluyen:</p><ul><li>Crear mundos completos en el Espacio de Aislamiento, incluidos materia, energía, leyes y vida</li><li>Diseñar y formular los sistemas de leyes fundamentales de los nuevos mundos</li><li>El dominio personal puede expandirse a un mundo completo</li><li>La forma de vida se aproxima a la existencia de alta dimensión, capaz de manifestarse simultáneamente en múltiples planos</li></ul><p>Los expertos del Nivel de Creación de Mundos son existencias de &quot;nivel mundo&quot;, cuyos mundos creados pueden servir como recursos de cultivo, sitios de experimentos, refugios de civilización, etc. El avance es uno de los eventos más raros del universo.</p><h3 id="_3-9-noveno-nivel-el-origen" tabindex="-1">3.9 Noveno Nivel: el Origen <a class="header-anchor" href="#_3-9-noveno-nivel-el-origen" aria-label="Permalink to &quot;3.9 Noveno Nivel: el Origen&quot;">​</a></h3><p>El núcleo del Nivel del Origen es el &quot;Origen&quot;. Los estándares para alcanzarlo incluyen:</p><ul><li>Tocar las leyes del Origen del universo, capaz de comprender las leyes últimas de funcionamiento del universo</li><li>Participar en el ajuste fino y la optimización de las leyes cósmicas, influyendo en la dirección evolutiva del universo</li><li>La forma de vida se conecta profundamente con el Origen del universo, casi inmortal</li><li>Movilizar la fuerza del Origen a escala cósmica</li></ul><p>Los expertos del Nivel del Origen son existencias de &quot;nivel cósmico&quot;, la fuerza más suprema de Heng Yuan Zhou. Los cultivadores que alcanzan este nivel son generalmente llamados &quot;expertos supremos de planos&quot;, el grupo objetivo central de la &quot;Estrategia de Activación del 20%&quot; de la civilización simbiótica.</p><h2 id="iv-mecanismo-de-certificacion-de-niveles" tabindex="-1">IV. Mecanismo de Certificación de Niveles <a class="header-anchor" href="#iv-mecanismo-de-certificacion-de-niveles" aria-label="Permalink to &quot;IV. Mecanismo de Certificación de Niveles&quot;">​</a></h2><p>Para garantizar la justicia y exactitud de la evaluación de niveles, la civilización simbiótica ha establecido un estricto mecanismo de certificación de niveles:</p><ol><li><strong>Monitoreo automático de anclas</strong>: tras conectarse el cultivador a la red de anclas, el ancla monitorea continuamente indicadores como el nivel energético, la comprensión de leyes y la intensidad de conciencia; cuando los indicadores alcanzan el estándar de un nuevo nivel, lo señala automáticamente</li><li><strong>Evaluación del Comité de Estándares</strong>: para los avances de nivel cuarto y superiores, el Comité de Estándares de Cultivo debe organizar una evaluación formal, que cubre tres aspectos: prueba teórica, prueba de combate práctico y evaluación de contribuciones</li><li><strong>Anuncio público y período de objeción</strong>: tras aprobar la evaluación, sigue un período de anuncio público de treinta días; durante este período cualquier vida puede presentar objeciones, y si una objeción se sustenta, se requiere una re-evaluación</li><li><strong>Emisión del certificado de nivel</strong>: tras finalizar el período de anuncio sin objeciones, la red de anclas emite un certificado de nivel unificado, y la información del certificado se registra en la base de datos de la civilización</li></ol><h2 id="v-niveles-y-derechos-y-obligaciones-sociales-correspondientes" tabindex="-1">V. Niveles y Derechos y Obligaciones Sociales Correspondientes <a class="header-anchor" href="#v-niveles-y-derechos-y-obligaciones-sociales-correspondientes" aria-label="Permalink to &quot;V. Niveles y Derechos y Obligaciones Sociales Correspondientes&quot;">​</a></h2><p>Los cultivadores de diferentes niveles disfrutan de diferentes derechos y asumen diferentes obligaciones en la civilización simbiótica:</p><table tabindex="0"><thead><tr><th>Nivel</th><th>Derechos Centrales</th><th>Obligaciones Centrales</th></tr></thead><tbody><tr><td>Percepción – Condensación del Origen</td><td>Acceso gratuito a recursos de cultivo básicos, derecho de uso de lugares públicos de cultivo</td><td>Respetar la ética del cultivo, participar en servicios comunitarios básicos</td></tr><tr><td>Transformación – Ley del Origen</td><td>Derecho de asignación de recursos avanzados, derecho de solicitud de calificación de mentor, derecho de movilidad interregional</td><td>Guiar a cultivadores principiantes, participar en I+D tecnológica o servicios sociales</td></tr><tr><td>Dao – Integración del Dao</td><td>Derecho de asignación de recursos de alto nivel, derecho de acceso a niveles superiores de anclas, derecho de participación en decisiones de la civilización</td><td>Emprender proyectos de investigación de nivel civilización, mantener la estabilidad de anclas regionales</td></tr><tr><td>Ruptura de Fronteras – Creación de Mundos</td><td>Derecho de asignación de recursos de nivel plano, derecho de creación de espacios independientes, derecho de participación en asuntos de planos</td><td>Emprender tareas de nivel plano, mantener la estabilidad de las membranas de planos, participar en asuntos entre planos</td></tr><tr><td>el Origen</td><td>Derecho de asignación de recursos de nivel cósmico, derecho de participación en el ajuste fino de leyes, derecho de participación en las decisiones supremas de la civilización</td><td>Mantener la estabilidad global del universo, guiar la dirección de la evolución de la civilización, formar talentos de reserva</td></tr></tbody></table><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>El estándar unificado de división de niveles de cultivo es una de las infraestructuras del sistema de cultivo de la Civilización Simbiótica del Ancla. Proporciona una &quot;medida&quot; común para los Trescientos Sistemas de Cultivo, haciendo posible la comunicación, colaboración y competencia entre sistemas, y proporcionando una base objetiva para la asignación de recursos, la gobernanza social y la formación de talentos. La división de los nueve niveles no busca crear diferencias jerárquicas, sino marcar claramente la etapa evolutiva de cada cultivador, proporcionándole el apoyo y la orientación más adecuados. La elevación de niveles no es un punto final, sino un nuevo punto de partida hacia una evolución simbiótica de nivel superior.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>10-三百套本源修炼体系总览 (Panorama de los Trescientos Sistemas de Cultivo del Origen)</li><li>17-位面至高强者标准 (Estándares de Expertos Supremos de Planos)</li><li>29-共生度评估体系 (Sistema de Evaluación del Grado de Simbiosis)</li></ul>',57)])])}const m=a(o,[["render",d]]);export{p as __pageData,m as default};
